import 'package:flutter/material.dart';
import 'package:phone_state/phone_state.dart';
import 'package:permission_handler/permission_handler.dart';

void main() {
  runApp(const MyApp());
}

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Call Listener',
      theme: ThemeData(primarySwatch: Colors.blue),
      home: const CallListenerPage(),
    );
  }
}

class CallListenerPage extends StatefulWidget {
  const CallListenerPage({super.key});

  @override
  State<CallListenerPage> createState() => _CallListenerPageState();
}

class _CallListenerPageState extends State<CallListenerPage> {
  String _status = "Очікування дозволів...";

  @override
  void initState() {
    super.initState();
    _initPhoneState();
  }

  // Запит дозволів та ініціалізація прослуховування дзвінків
  Future<void> _initPhoneState() async {
    // Просимо дозвіл на читання стану телефону
    var status = await Permission.phone.request();

    if (status.isGranted) {
      setState(() {
        _status = "Слухаємо дзвінки...";
      });

      // Слухаємо стан дзвінка
      PhoneState.stream.listen((event) {
        setState(() {
          if (event.status == PhoneStateStatus.RINGING) {
            _status = "УВАГА: Вхідний дзвінок! (Звонимо на ESP32)";
            // ТУТ МИ ПІЗНІШЕ ДОДАШЕМО HTTP-ЗАПИТ НА ТРВУ ПЛАТУ
          } else if (event.status == PhoneStateStatus.CALL_STARTED) {
            _status = "Дзвінок прийнято";
          } else if (event.status == PhoneStateStatus.NOTHING) {
            _status = "Телефон спокійний";
          }
        });
      });
    } else {
      setState(() {
        _status = "Доступ до телефонії відхилено!";
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Інформатор для дзвінків')),
      body: Center(
        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Text(
            _status,
            textAlign: TextAlign.center,
            style: const TextStyle(fontSize: 22, fontWeight: FontWeight.bold),
          ),
        ),
      ),
    );
  }
}
